cssHead:
body {
  font-family: 'Geist', -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}
.font-serif-headline {
  font-family: 'EB Garamond', serif;
}


/* Subtle radial orb simulating MIA sphere logo */
.mia-sphere {
  background: radial-gradient(circle at 35% 30%, #A5BDAE 0%, #7F9A86 50%, #5B7563 80%, #D8A54B 105%);
  box-shadow: 0 2px 6px rgba(40, 62, 53, 0.15);
}
/* Ambient warm gradient on top */
.top-ambient-glow {
  background: radial-gradient(50% 120px at 50% 0%, #FBF1DC 0%, rgba(246, 247, 244, 0) 100%);
}
